-- ROOT ONLY, after both reviewed migrations. This is SQL metadata/authority proof, not a blob upload.
-- Separate real deployed Edge -> private Storage byte readback gate is REQUIRED before capability acceptance.
BEGIN;
SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='30s';SET LOCAL idle_in_transaction_session_timeout='60s';
CREATE TEMP TABLE document_finalizer_results(label text PRIMARY KEY,passed boolean)ON COMMIT DROP;
GRANT INSERT,SELECT ON document_finalizer_results TO authenticated,service_role;
CREATE FUNCTION pg_temp.document_finalizer_assert(ok boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'document_finalizer_assert_failed:%',label;END IF;INSERT INTO pg_temp.document_finalizer_results VALUES(label,true);END$$;
DO $qa$ DECLARE
 executor name:=current_user;
 known_ws constant uuid:='053a5656-b19b-48a4-8721-65c4674f647c';actor constant uuid:='21a04e78-e3b1-448e-8517-47aad25dd5da';account constant uuid:='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd';
 ws constant uuid:='a3c01504-1015-4000-8000-000000000001';other_profile constant uuid:='a3c01504-1015-4000-8000-000000000002';nonce constant uuid:='a3c01504-1015-4000-8000-000000000003';nonce2 constant uuid:='a3c01504-1015-4000-8000-000000000004';sid1 constant uuid:='a3c01504-1015-4000-8000-000000000005';sid2 constant uuid:='a3c01504-1015-4000-8000-000000000006';
 -- SHA256 of deterministic fixture bytes %PDF-1.7\n; SQL does not assert these bytes exist in Storage.
 digest constant text:='0716f9264c9fe19f5d7455276107f3ddcc1d3497f63d60689a73558ae8a1bf5e';
 real_sid uuid;c jsonb;p jsonb;u jsonb;u2 jsonb;r jsonb;receipt jsonb;replay jsonb;denied boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM zoi.workspaces w JOIN zoi.workspace_members m ON m.workspace_id=w.id JOIN zoi.user_profiles up ON up.id=m.profile_id JOIN auth.users au ON au.id=up.auth_user_id WHERE w.id=known_ws AND w.name='Zoi isolated QA 2026-09-30'AND w.owner_profile_id=actor AND m.profile_id=actor AND m.role='owner'AND up.auth_user_id=account AND au.email_confirmed_at IS NOT NULL AND au.deleted_at IS NULL AND NOT coalesce(au.is_anonymous,false)AND(au.banned_until IS NULL OR au.banned_until<=clock_timestamp()))THEN RAISE EXCEPTION 'dedicated_qa_authority_unavailable';END IF;
 SELECT id INTO real_sid FROM auth.sessions WHERE user_id=account AND(not_after IS NULL OR not_after>clock_timestamp())ORDER BY created_at DESC NULLS LAST LIMIT 1;IF real_sid IS NULL THEN RAISE EXCEPTION 'dedicated_qa_current_session_unavailable';END IF;
 IF EXISTS(SELECT 1 FROM zoi.workspaces WHERE id=ws)OR EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id=other_profile)OR EXISTS(SELECT 1 FROM auth.sessions WHERE id IN(sid1,sid2))OR EXISTS(SELECT 1 FROM zoi.document_versions WHERE request_id IN(nonce,nonce2))THEN RAISE EXCEPTION 'document_finalizer_fixture_collision';END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id='workspace-documents'AND public=false)THEN RAISE EXCEPTION 'private_document_bucket_unavailable';END IF;
 INSERT INTO zoi.user_profiles(id,display_name)VALUES(other_profile,'Rollback-only finalizer synthetic profile');
 INSERT INTO zoi.workspaces(id,name,kind,owner_profile_id,created_by_auth)VALUES(ws,'Rollback-only finalizer foundation 20261015','business',actor,account);
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at,not_after)VALUES(sid1,account,clock_timestamp(),clock_timestamp(),clock_timestamp()+interval'10 minutes'),(sid2,account,clock_timestamp(),clock_timestamp(),clock_timestamp()+interval'10 minutes');
 PERFORM set_config('request.jwt.claim.sub',account::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid1)::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 c:=public.ops_record_save(ws,'company','{"title":"Rollback finalizer company"}',null,0);p:=public.ops_record_save(ws,'project',jsonb_build_object('title','Rollback private project','company_id',c#>>'{record,id}'),null,0);
 u:=public.document_upload_begin(ws,(p#>>'{record,id}')::uuid,null,0,'Rollback private PDF',nonce,'proof.pdf','application/pdf',9,digest);PERFORM pg_temp.document_finalizer_assert(u->>'ok'='true','actual_owner_without_member_reserves_canonical_version');
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,digest);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.document_finalizer_assert(denied,'verified_finalizer_service_only');
 EXECUTE format('SET LOCAL ROLE %I',executor);
 INSERT INTO storage.objects(bucket_id,name,metadata)VALUES('workspace-documents',u#>>'{upload,object_path}','{"size":9,"mimetype":"application/pdf"}');
 PERFORM pg_temp.document_finalizer_assert((SELECT count(*)=1 FROM zoi.document_upload_authority_grants WHERE version_id=(u#>>'{upload,id}')::uuid AND account_id=account AND session_id=sid1),'original_authority_grant_recorded');
 EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.document_upload_finish((u#>>'{upload,id}')::uuid);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='upload_verified_completion_required';END;PERFORM pg_temp.document_finalizer_assert(denied,'legacy_metadata_pending_write_closed');
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,repeat('b',64));EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='uploaded_object_hash_mismatch';END;PERFORM pg_temp.document_finalizer_assert(denied,'digest_must_match_immutable_reservation');
 EXECUTE format('SET LOCAL ROLE %I',executor);DELETE FROM auth.sessions WHERE id=sid1;EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,digest);EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='upload_session_unavailable';END;PERFORM pg_temp.document_finalizer_assert(denied,'revoked_original_session_refuses_service_finish');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid2)::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 replay:=public.document_upload_begin(ws,(p#>>'{record,id}')::uuid,null,0,'Rollback private PDF',nonce,'proof.pdf','application/pdf',9,digest);PERFORM pg_temp.document_finalizer_assert(replay#>>'{upload,id}'=u#>>'{upload,id}','explicit_relogin_resume_keeps_original_nonce_version');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM pg_temp.document_finalizer_assert((SELECT count(*)=2 FROM zoi.document_upload_authority_grants WHERE version_id=(u#>>'{upload,id}')::uuid),'grant_renewal_is_append_only');EXECUTE 'SET LOCAL ROLE service_role';
 receipt:=public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,digest);replay:=public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,digest);PERFORM pg_temp.document_finalizer_assert(receipt=replay AND receipt#>>'{version,state}'='ready','canonical_service_finish_and_lost_response_exact_repeat');
 r:=public.document_upload_finish((u#>>'{upload,id}')::uuid);PERFORM pg_temp.document_finalizer_assert(r#>>'{version,state}'='ready'AND r->>'content_verified'='false','legacy_ready_recovery_has_no_blob_verification_claim');
 EXECUTE 'SET LOCAL ROLE authenticated';r:=public.documents_list(ws,null);PERFORM pg_temp.document_finalizer_assert(r->>'role'='owner'AND r#>>'{documents,0,current_version}'='1','private_documents_owner_readback');
 r:=public.document_history(ws,(u#>>'{document,id}')::uuid);PERFORM pg_temp.document_finalizer_assert(r#>>'{versions,0,state}'='ready','private_version_history_readback');
 r:=public.document_download_authorize(ws,(u#>>'{upload,id}')::uuid);PERFORM pg_temp.document_finalizer_assert(r->>'object_path'=u#>>'{upload,object_path}'AND r->>'expires_in'='60','current_owner_download_authorization');
 u2:=public.document_upload_begin(ws,(p#>>'{record,id}')::uuid,null,0,'Rollback changed policy',nonce2,'proof.pdf','application/pdf',9,digest);
 EXECUTE format('SET LOCAL ROLE %I',executor);INSERT INTO storage.objects(bucket_id,name,metadata)VALUES('workspace-documents',u2#>>'{upload,object_path}','{"size":10,"mimetype":"application/pdf"}');EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u2#>>'{upload,id}')::uuid,digest);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='uploaded_object_mismatch';END;PERFORM pg_temp.document_finalizer_assert(denied,'actual_storage_metadata_size_check_retained');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE storage.objects SET metadata='{"size":9,"mimetype":"application/pdf"}'WHERE bucket_id='workspace-documents'AND name=u2#>>'{upload,object_path}';UPDATE zoi.workspaces SET owner_profile_id=other_profile WHERE id=ws;INSERT INTO zoi.workspace_members(workspace_id,profile_id,role)VALUES(ws,actor,'owner');EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u2#>>'{upload,id}')::uuid,digest);EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='upload_permission_changed';END;PERFORM pg_temp.document_finalizer_assert(denied,'ownership_transfer_and_forged_owner_refuse_finish');
 EXECUTE format('SET LOCAL ROLE %I',executor);DELETE FROM zoi.workspace_members WHERE workspace_id=ws;UPDATE zoi.workspaces SET owner_profile_id=actor WHERE id=ws;UPDATE zoi.workspace_documents SET archived_at=clock_timestamp()WHERE id=(u#>>'{document,id}')::uuid;EXECUTE 'SET LOCAL ROLE service_role';
 denied:=false;BEGIN PERFORM public.document_upload_finish_verified((u#>>'{upload,id}')::uuid,digest);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='upload_state_conflict';END;PERFORM pg_temp.document_finalizer_assert(denied,'ready_receipt_does_not_resurrect_archived_document');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM pg_temp.document_finalizer_assert((SELECT count(*)=1 FROM zoi.document_audit WHERE version_id=(u#>>'{upload,id}')::uuid AND action='uploaded'),'exactly_one_uploaded_audit_after_replays');
 PERFORM pg_temp.document_finalizer_assert((SELECT owner_profile_id=actor FROM zoi.workspaces WHERE id=known_ws)AND(SELECT role='owner'FROM zoi.workspace_members WHERE workspace_id=known_ws AND profile_id=actor)AND(SELECT not_after IS NULL OR not_after>clock_timestamp()FROM auth.sessions WHERE id=real_sid AND user_id=account),'real_qa_authority_and_session_unchanged');
END $qa$;
SELECT label,passed FROM document_finalizer_results ORDER BY label;
ROLLBACK;
SELECT jsonb_build_object('rollback_completed',true,'workspace_absent',NOT EXISTS(SELECT 1 FROM zoi.workspaces WHERE id='a3c01504-1015-4000-8000-000000000001'),'synthetic_profile_absent',NOT EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id='a3c01504-1015-4000-8000-000000000002'),'synthetic_sessions_absent',NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id IN('a3c01504-1015-4000-8000-000000000005','a3c01504-1015-4000-8000-000000000006')),'records_absent',NOT EXISTS(SELECT 1 FROM zoi.ops_records WHERE workspace_id='a3c01504-1015-4000-8000-000000000001'),'documents_absent',NOT EXISTS(SELECT 1 FROM zoi.workspace_documents WHERE workspace_id='a3c01504-1015-4000-8000-000000000001'),'versions_absent',NOT EXISTS(SELECT 1 FROM zoi.document_versions WHERE workspace_id='a3c01504-1015-4000-8000-000000000001'),'authority_grants_absent',NOT EXISTS(SELECT 1 FROM zoi.document_upload_authority_grants WHERE workspace_id='a3c01504-1015-4000-8000-000000000001'),'storage_metadata_absent',NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='workspace-documents'AND name LIKE'a3c01504-1015-4000-8000-000000000001/%'),'document_audit_absent',NOT EXISTS(SELECT 1 FROM zoi.document_audit WHERE workspace_id='a3c01504-1015-4000-8000-000000000001'),'actual_storage_body_checked',false,'provider_calls',0);
